// Lấy dữ liệu từ webhook
const command = $json.command;
const timestamp = $json.timestamp;
const userId = $json.userId;

// Log lệnh nhận được
console.log('Received command:', command);

// Xử lý logic nghiệp vụ ở đây
// Ví dụ: phân tích sentiment, gọi AI API, truy vấn database...

// Tạo phản hồi
let response = '';

// Xử lý một số lệnh đơn giản
if (command.toLowerCase().includes('xin chào') || command.toLowerCase().includes('hello')) {
  response = 'Xin chào! Tôi là trợ lý ảo của bạn. Tôi có thể giúp gì cho bạn?';
} else if (command.toLowerCase().includes('thời gian') || command.toLowerCase().includes('time')) {
  const now = new Date();
  response = `Bây giờ là ${now.toLocaleString('vi-VN')}`;
} else if (command.toLowerCase().includes('cảm ơn') || command.toLowerCase().includes('thank')) {
  response = 'Không có gì! Tôi luôn sẵn sàng giúp đỡ bạn.';
} else {
  response = `Tôi đã nhận được lệnh: "${command}". Cảm ơn bạn đã sử dụng trợ lý giọng nói!`;
}

// Trả về dữ liệu để gửi qua SSE
return {
  processedCommand: command,
  response: response,
  timestamp: new Date().toISOString(),
  userId: userId,
  status: 'processed'
};
